<?php
declare(strict_types=1);
namespace PlusChat\Auth;
use PlusChat\Database;use PlusChat\Http\Request;use PlusChat\Http\Response;use PlusChat\Security\Security;
final class PasswordController{
 public function requestReset(Request $r):Response{$b=$r->json();$email=strtolower(trim((string)($b['email']??'')));$p=Database::pdo();$st=$p->prepare('SELECT id FROM users WHERE email=:e');$st->execute(['e'=>$email]);$id=$st->fetchColumn();if($id){$raw=Security::token(32);$p->prepare('UPDATE password_resets SET used_at=NOW() WHERE user_id=:u AND used_at IS NULL')->execute(['u'=>$id]);$p->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(:u,:t,NOW()+INTERVAL \'30 minutes\')')->execute(['u'=>$id,'t'=>hash('sha256',$raw,true)]);$mailer=new Mailer();try{$mailer->send($email,'Восстановление пароля PlusChat','<p>Код/ссылка восстановления: <b>'.htmlspecialchars($raw,ENT_QUOTES,'UTF-8').'</b></p>','Код восстановления: '.$raw);}catch(\Throwable $e){error_log('reset mail failed: '.$e->getMessage());}}return Response::json(['ok'=>true]);}
 public function reset(Request $r):Response{$b=$r->json();$email=strtolower(trim((string)($b['email']??'')));$token=(string)($b['token']??'');$password=(string)($b['password']??'');if(strlen($password)<10||$token==='')return Response::json(['error'=>'invalid_input'],422);$p=Database::pdo();$st=$p->prepare('SELECT pr.id,pr.user_id FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE u.email=:e AND pr.token_hash=:t AND pr.expires_at>NOW() AND pr.used_at IS NULL');$st->execute(['e'=>$email,'t'=>hash('sha256',$token,true)]);$row=$st->fetch();if(!$row)return Response::json(['error'=>'invalid_token'],400);$p->beginTransaction();$p->prepare('UPDATE users SET password_hash=:h,updated_at=NOW() WHERE id=:u')->execute(['h'=>Security::hashPassword($password),'u'=>$row['user_id']]);$p->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=:id')->execute(['id'=>$row['id']]);$p->prepare('UPDATE sessions SET revoked_at=NOW() WHERE user_id=:u')->execute(['u'=>$row['user_id']]);$p->commit();return Response::json(['ok'=>true]);}
}
